pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    function setUp() public { c = new PRIVATE_ETH_CELL(); }
    function testRegression_property() public {
        c.Initialized();
        vm.prank(address(0xdead));
        bool ok;
        try c.SetMinSum(100) { ok = true; } catch { ok = false; }
        assertEq(c.MinSum(), 0);
    }
}
